const pins=Object.freeze({...OWN_PAYROLL_LOGIN_SOURCE_PINS,...OWN_PAYROLL_LOGIN_READER_SOURCE_PINS});
export function projectOwnPayrollLoginRawSourceToParent(file,value){
 assert.equal(typeof file,'string','OWN_LOGIN_SOURCE_PATH_REQUIRED');
 assert.ok(Buffer.isBuffer(value),'OWN_LOGIN_RAW_SOURCE_REQUIRED');
 const pin=Object.hasOwn(pins,file)?pins[file]:null;if(!pin)return value;
 assert.equal(value.length,pin.afterBytes,'OWN_LOGIN_CURRENT_BYTES:'+file);
 assert.equal(hash(value),pin.afterSha256,'OWN_LOGIN_CURRENT_SHA:'+file);
 let source=value;
 for(const op of [...pin.inverse].reverse()){
  const after=Buffer.from(op.afterBase64,'base64'),before=Buffer.from(op.beforeBase64,'base64');
  assert.deepEqual(source.subarray(op.afterOffset,op.afterOffset+after.length),after,'OWN_LOGIN_EXACT_INVERSE_SPAN:'+file);
  source=Buffer.concat([source.subarray(0,op.afterOffset),before,source.subarray(op.afterOffset+after.length)]);
 }
 assert.equal(source.length,pin.beforeBytes,'OWN_LOGIN_PARENT_BYTES:'+file);
 assert.equal(hash(source),pin.beforeSha256,'OWN_LOGIN_PARENT_SHA:'+file);return source;
}
